# owner: platform
"""Weekly timesheet rows, one line of text per worker."""

from typing import Dict, Iterable, List, Tuple

from hourglass.models import Shift


def _check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker name")


def _totals(shifts: List[Shift]) -> Dict[str, Tuple[int, int]]:
    totals = {}
    for shift in shifts:
        count, minutes = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (count + 1, minutes + shift.span.minutes)
    return totals


def _row(name: str, count: int, minutes: int) -> str:
    return f"{name}: {count} shifts, {minutes / 60:.1f} hours"


# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, like Ana: 3 shifts, 12.5 hours, busiest first.

    Raises ValueError for an empty schedule or a blank worker name.
    """
    shifts = list(shifts)
    _check_shifts(shifts)
    totals = _totals(shifts)
    order = sorted(totals, key=lambda name: (-totals[name][1], name))
    return [_row(name, *totals[name]) for name in order]

