# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_one_decimal(self):
        shifts = [
            make_shift("Bo", 9, 12),
            make_shift("Ana", 9, 13),
            make_shift("Ana", 9, 13, "tue"),
            make_shift("Cy", 9, 10)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ana: 2 shifts, 8.0 hours",
                "Bo: 1 shifts, 3.0 hours",
                "Cy: 1 shifts, 1.0 hours"
            ]
        )

    def test_fractional_hours(self):
        shift = Shift("Ana", "mon", Span(9 * 60, 9 * 60 + 50))
        self.assertEqual(timesheet_lines([shift]), ["Ana: 1 shifts, 0.8 hours"])

    def test_ties_break_by_name(self):
        shifts = [make_shift("Bo", 9, 10), make_shift("Ana", 9, 10)]
        names = [line.split(":")[0] for line in timesheet_lines(shifts)]
        self.assertEqual(names, ["Ana", "Bo"])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for blank in ("", "   "):
            with self.assertRaises(ValueError):
                timesheet_lines([make_shift(blank, 9, 10)])
